ALTER TYPE "OrganizationSequenceType" ADD VALUE 'INVOICE'; CREATE TYPE "InvoiceStatus" AS ENUM ('DRAFT','FINALIZED','VOID');
CREATE TABLE "invoices" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"invoice_number" VARCHAR(64) NOT NULL,"customer_id" UUID NOT NULL,"subscription_id" UUID,"status" "InvoiceStatus" NOT NULL DEFAULT 'DRAFT',"currency_code" CHAR(3) NOT NULL,"issue_date" DATE NOT NULL,"due_date" DATE NOT NULL,"subtotal" DECIMAL(19,4) NOT NULL DEFAULT 0,"discount_total" DECIMAL(19,4) NOT NULL DEFAULT 0,"tax_total" DECIMAL(19,4) NOT NULL DEFAULT 0,"grand_total" DECIMAL(19,4) NOT NULL DEFAULT 0,"finalized_at" TIMESTAMPTZ(6),"voided_at" TIMESTAMPTZ(6),"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "invoices_pkey" PRIMARY KEY("id"),CONSTRAINT "invoices_dates_check" CHECK("due_date">="issue_date"));
CREATE TABLE "invoice_items" ("id" UUID NOT NULL,"invoice_id" UUID NOT NULL,"description" VARCHAR(2000) NOT NULL,"quantity" INTEGER NOT NULL,"unit_price" DECIMAL(19,4) NOT NULL,"discount_amount" DECIMAL(19,4) NOT NULL DEFAULT 0,"tax_amount" DECIMAL(19,4) NOT NULL DEFAULT 0,"line_subtotal" DECIMAL(19,4) NOT NULL DEFAULT 0,"line_total" DECIMAL(19,4) NOT NULL DEFAULT 0,"currency_code" CHAR(3) NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "invoice_items_pkey" PRIMARY KEY("id"),CONSTRAINT "invoice_items_quantity_check" CHECK("quantity">0));
CREATE UNIQUE INDEX "invoices_organization_id_invoice_number_key" ON "invoices"("organization_id","invoice_number");CREATE INDEX "invoices_organization_id_status_due_date_idx" ON "invoices"("organization_id","status","due_date");CREATE INDEX "invoice_items_invoice_id_idx" ON "invoice_items"("invoice_id");
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_organization_fkey" FOREIGN KEY("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "invoices" ADD CONSTRAINT "invoices_customer_fkey" FOREIGN KEY("organization_id","customer_id") REFERENCES "customers"("organization_id","id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "invoice_items" ADD CONSTRAINT "invoice_items_invoice_fkey" FOREIGN KEY("invoice_id") REFERENCES "invoices"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
